{
  "PROP-6a4369e9-inv-027": {
    "property_id": "PROP-6a4369e9-inv-027",
    "audit_result": {
      "property_id": "PROP-6a4369e9-inv-027",
      "classification": "vulnerability",
      "code_path": "consensus/types/src/chain_spec.rs::min_epoch_data_availability_boundary::L828-830",
      "proof_trace": "When blob_retention_epoch > fulu_fork_epoch, line 829 returns current_epoch - MIN_EPOCHS_FOR_DATA_COLUMN_SIDECARS_REQUESTS without enforcing max(result, FULU_FORK_EPOCH). During the window where current_epoch < FULU_FORK_EPOCH + MIN_EPOCHS_FOR_DATA_COLUMN_SIDECARS_REQUESTS, the boundary can be set below FULU_FORK_EPOCH, violating the invariant.",
      "attack_scenario": "Within 4096 epochs after Fulu fork (when blob_retention_epoch > fulu_fork_epoch but current_epoch - 4096 < fulu_fork_epoch), an attacker can send DataColumnsByRangeRequest for slots before FULU_FORK_EPOCH, requesting data that should not exist (pre-fork). This causes nodes to accept requests for invalid epoch ranges, potentially causing DoS or inconsistent sync state.",
      "checklist_id": "PROP-6a4369e9-inv-027"
    },
    "text": "data_column_serve_range lower bound must be max(current_epoch - MIN_EPOCHS, FULU_FORK_EPOCH).",
    "assertion": "serve_range.start == max(current_epoch - MIN_EPOCHS_FOR_DATA_COLUMN_SIDECARS_REQUESTS, FULU_FORK_EPOCH)",
    "covers": "SG-008",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

